{
  "openapi": "3.0.3",
  "info": {
    "title": "Script manual and call workflow API",
    "version": "1.0.0",
    "description": "Endpoints generated from the BPMN process `Process_Mixed`."
  },
  "paths": {
    "/health": {
      "get": {
        "summary": "Check that the service is running",
        "responses": {
          "200": {
            "description": "The service is up",
            "content": {
              "application/json": {
                "example": {
                  "status": "ok",
                  "workflow": "Process_Mixed"
                }
              }
            }
          }
        }
      }
    },
    "/workflows/process_mixed/execute": {
      "post": {
        "summary": "Run the workflow from start to end with the given process variables",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "payload": {
                    "type": "object",
                    "description": "Process variables read by forms, conditions and tasks.",
                    "properties": {
                      "amount": {
                        "type": "number"
                      },
                      "ok": {
                        "type": "boolean"
                      },
                      "result": {
                        "type": "string"
                      }
                    }
                  }
                }
              },
              "example": {
                "payload": {
                  "amount": 100,
                  "ok": true,
                  "result": "sample_result"
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "The workflow ran",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "completed": {
                      "type": "boolean"
                    },
                    "status": {
                      "type": "string"
                    },
                    "visited_nodes": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    },
                    "enqueued_jobs": {
                      "type": "array",
                      "items": {
                        "type": "object"
                      }
                    },
                    "context": {
                      "type": "object"
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
